public class Bar {
   private String getPassword()
   {
      byte[] encoded = GlobalConfigMap.
         getInstance().
         getVault().
         secret("database.password").
         getValue();

      byte[] decoded = Base64.
         getDecoder().
         decode(encoded);

      return new String(decoded, StandardCharsets.UTF_8);
   }
}

public class Bar {
   private String getPassword()
   {
      byte[] decoded;
      byte[] encoded;

      encoded = GlobalConfigMap.
         getInstance().
         getVault().
         secret("database.password").
         getValue();

      decoded = Base64.
         getDecoder().
         decode(encoded);

      return new String(decoded, StandardCharsets.UTF_8);
   }
}
